def _extrude_poly(poly: Any, height: float) -> trimesh.Trimesh:
    if poly.geom_type == 'MultiPolygon':
        ms = [trimesh.creation.extrude_polygon(p, height=height) for p in poly.geoms if not p.is_empty]
        return trimesh.util.concatenate(ms)
    return trimesh.creation.extrude_polygon(poly, height=height)

def get_real_heart_polygon(heart_width: float = 50.0) -> sg.Polygon:
    """
    Restituisce la sagoma fedele del cuore pieno, morbido e rotondo
    estratto da Screenshot 2026-10-23 152932.png e reso simmetrico a X=0.
    """
    poly = wkt.loads(REAL_HEART_WKT)
    b = poly.bounds
    w_orig = b[2] - b[0]
    scale = heart_width / max(w_orig, 1e-6)
    if abs(scale - 1.0) > 1e-5:
        return affinity.scale(poly, xfact=scale, yfact=scale, origin=(0, 0))
    return poly

def get_canon_heart_polygon(heart_width: float = 50.0) -> sg.Polygon:
    return get_real_heart_polygon(heart_width=heart_width)

def get_authentic_huntrix_blocks(target_width: float = 55.0, letter_gap_mm: float = 0.95) -> Dict[str, Any]:
    """
    Estrae e separa fisicamente i 4 blocchi autonomi del logo autentico HUNTRIX:
    - Blocco 1: H (autonoma)
    - Blocco 2: U (autonoma)
    - Blocco 3: N (autonoma)
    - Blocco 4: TRX (blocco unito con barra della T sopra la R e diagonale della R fusa nella X)
    Imposta una fuga orizzontale netta (fuga/gap d'aria) di ~0.95 mm tra H-U, U-N e N-TRX.
    """
    raw_logo = wkt.loads(HUNTRIX_NORM_TEXT_WKT)
    p0 = raw_logo.geoms[0]  # Asta verticale T
    p1 = raw_logo.geoms[1]  # H e U (congiunte nel WKT grezzo)
    p2 = raw_logo.geoms[2]  # N
    p3 = raw_logo.geoms[3]  # Diagonale destra X
    p4 = raw_logo.geoms[4]  # R e diagonale sinistra X
    p5 = raw_logo.geoms[5]  # Cuspide/taglio superiore sinistro H
    p6 = raw_logo.geoms[6]  # Barra superiore orizzontale T

    s = 55.0
    p0_s = affinity.scale(p0, xfact=s, yfact=s, origin=(0, 0))
    p1_s = affinity.scale(p1, xfact=s, yfact=s, origin=(0, 0))
    p2_s = affinity.scale(p2, xfact=s, yfact=s, origin=(0, 0))
    p3_s = affinity.scale(p3, xfact=s, yfact=s, origin=(0, 0))
    p4_s = affinity.scale(p4, xfact=s, yfact=s, origin=(0, 0))
    p5_s = affinity.scale(p5, xfact=s, yfact=s, origin=(0, 0))
    p6_s = affinity.scale(p6, xfact=s, yfact=s, origin=(0, 0))

    # Taglio netto tra H e U: elimina i ponti orizzontali di fusione
    box_cut = sg.box(-18.9, -10.0, -16.4, 10.0)
    p1_clean = p1_s.difference(box_cut)
    poly_H = unary_union([p1_clean.geoms[0], p5_s])
    poly_U_orig = p1_clean.geoms[1]
    poly_N_orig = p2_s
    poly_TRX_orig = unary_union([p0_s, p6_s, p4_s, p3_s])

    gap = letter_gap_mm * (target_width / 55.0)

    # 1. Posizionamento U con gap da H
    u_shift = (poly_H.bounds[2] + gap) - poly_U_orig.bounds[0]
    poly_U = affinity.translate(poly_U_orig, xoff=u_shift)

    # 2. Posizionamento N con gap da U
    n_shift = (poly_U.bounds[2] + gap) - poly_N_orig.bounds[0]
    poly_N = affinity.translate(poly_N_orig, xoff=n_shift)

    # 3. Posizionamento TRX con gap da N
    trx_shift = (poly_N.bounds[2] + gap) - poly_TRX_orig.bounds[0]
    poly_TRX = affinity.translate(poly_TRX_orig, xoff=trx_shift)

    flat_polys = []
    for p in [poly_H, poly_U, poly_N, poly_TRX]:
        if p.geom_type == 'Polygon':
            flat_polys.append(p)
        elif p.geom_type == 'MultiPolygon':
            flat_polys.extend(list(p.geoms))
    multi = sg.MultiPolygon(flat_polys)

    # Riscalatura proporzionata e centratura a X=0
    curr_w = multi.bounds[2] - multi.bounds[0]
    scale_fac = target_width / max(curr_w, 1e-6)
    poly_H = affinity.scale(poly_H, xfact=scale_fac, yfact=scale_fac, origin=(0, 0))
    poly_U = affinity.scale(poly_U, xfact=scale_fac, yfact=scale_fac, origin=(0, 0))
    poly_N = affinity.scale(poly_N, xfact=scale_fac, yfact=scale_fac, origin=(0, 0))
    poly_TRX = affinity.scale(poly_TRX, xfact=scale_fac, yfact=scale_fac, origin=(0, 0))

    flat_polys = []
    for p in [poly_H, poly_U, poly_N, poly_TRX]:
        if p.geom_type == 'Polygon':
            flat_polys.append(p)
        elif p.geom_type == 'MultiPolygon':
            flat_polys.extend(list(p.geoms))
    multi = sg.MultiPolygon(flat_polys)

    center_x = (multi.bounds[0] + multi.bounds[2]) / 2.0
    poly_H = affinity.translate(poly_H, xoff=-center_x)
    poly_U = affinity.translate(poly_U, xoff=-center_x)
    poly_N = affinity.translate(poly_N, xoff=-center_x)
    poly_TRX = affinity.translate(poly_TRX, xoff=-center_x)

    flat_polys = []
    for p in [poly_H, poly_U, poly_N, poly_TRX]:
        if p.geom_type == 'Polygon':
            flat_polys.append(p)
        elif p.geom_type == 'MultiPolygon':
            flat_polys.extend(list(p.geoms))
    multi = sg.MultiPolygon(flat_polys)

    return {
        'H': poly_H,
        'U': poly_U,
        'N': poly_N,
        'TRX': poly_TRX,
        'logo': multi
    }

def get_authentic_huntrix_logo(
    target_width: float = 55.0,
    buffer_fdm: float = 0.0
) -> sg.MultiPolygon:
    """
    Restituisce il logo vettoriale autentico HUNTRIX con lettere H, U, N, TRX separate fisicamente
    da una fuga netta (gap d'aria >= 0.90 mm).
    """
    blocks = get_authentic_huntrix_blocks(target_width=target_width, letter_gap_mm=0.95)
    logo = blocks['logo']
    if buffer_fdm > 0:
        return logo.buffer(buffer_fdm, resolution=16)
    return logo

def get_huntrix_preset_a_geometries(target_width: float = 58.0) -> Dict[str, Any]:
    """
    Preset A: Geometria nativa 3D ufficiale del file master CAD (Huntrix+Keychain+without+loop.3mf)
    - Mesh 3D originali al 100%: Base_Contour e Mesh_Text native senza approssimazioni vettoriali
    - Asola anello integrata con diametro 3.80 mm e parete >= 2.30 mm, spessore Z pieno pari alla base
    - Scala contenuta entro 60.0 mm (target 58.0 mm)
    - Compenetrazione Z di 0.40 mm per coesione termica FDM
    - 100% manifold e watertight
    """
    npz_path = Path(__file__).resolve().parent / "huntrix_cad_native.npz"
    if npz_path.exists():
        data = np.load(npz_path)
        base_v = data["base_vertices"]
        base_f = data["base_faces"]
        text_v = data["text_vertices"]
        text_f = data["text_faces"]
        m_base = trimesh.Trimesh(vertices=base_v, faces=base_f, process=False)
        m_text = trimesh.Trimesh(vertices=text_v, faces=text_f, process=False)

        # Riscalatura proporzionata X/Y se richiesta diversa da 58.0 mm
        scale = target_width / 58.0
        if abs(scale - 1.0) > 1e-4:
            m_base = m_base.copy()
            m_text = m_text.copy()
            m_base.vertices[:, :2] *= scale
            m_text.vertices[:, :2] *= scale

        return {
            'base': m_base,
            'text': m_text,
            'base_mesh': m_base,
            'text_mesh': m_text
        }

    # Fallback su file master 3MF originale se NPZ non presente
    orig_3mf = Path(__file__).resolve().parent.parent.parent / "PROGETTI DEFINITIVI" / "Portachiavi_Huntrix" / "Huntrix+Keychain+without+loop.3mf"
    if orig_3mf.exists():
        import zipfile
        import xml.etree.ElementTree as ET
        from manifold3d import Manifold, Mesh

        zf = zipfile.ZipFile(orig_3mf)
        xml_content = zf.read("3D/Objects/object_1.model")
        root = ET.fromstring(xml_content)
        NS = {"m": "http://schemas.microsoft.com/3dmanufacturing/core/2015/02"}

        def extract_mesh(obj_id):
            obj = root.find(f'.//m:object[@id="{obj_id}"]', NS)
            mesh_el = obj.find("m:mesh", NS)
            vertices = np.array([[float(v.get("x")), float(v.get("y")), float(v.get("z"))] for v in mesh_el.findall(".//m:vertex", NS)], dtype=np.float64)
            triangles = np.array([[int(t.get("v1")), int(t.get("v2")), int(t.get("v3"))] for t in mesh_el.findall(".//m:triangle", NS)], dtype=np.int64)
            return trimesh.Trimesh(vertices=vertices, faces=triangles, process=False)

        m_base_raw = extract_mesh("1")
        m_text_raw = extract_mesh("2")
        m_base_raw.apply_translation([0, 0, -1])
        m_text_raw.apply_translation([0, 0, 1])

        target_base_width = target_width
        scale = target_base_width / (m_base_raw.bounds[1][0] - m_base_raw.bounds[0][0])
        m_base = m_base_raw.copy()
        m_text = m_text_raw.copy()
        m_base.vertices[:, :2] *= scale
        m_text.vertices[:, :2] *= scale

        center_x = (m_base.bounds[0][0] + m_base.bounds[1][0]) / 2.0
        center_y = (m_base.bounds[0][1] + m_base.bounds[1][1]) / 2.0
        m_base.apply_translation([-center_x, -center_y, 0])
        m_text.apply_translation([-center_x, -center_y, 0])

        target_base_h = 2.60
        base_z_min = m_base.bounds[0][2]
        base_curr_h = m_base.bounds[1][2] - base_z_min
        m_base.vertices[:, 2] = (m_base.vertices[:, 2] - base_z_min) * (target_base_h / base_curr_h)

        target_text_h = 1.40
        text_z_min = m_text.bounds[0][2]
        text_curr_h = m_text.bounds[1][2] - text_z_min
        m_text.vertices[:, 2] = 2.20 + (m_text.vertices[:, 2] - text_z_min) * (target_text_h / text_curr_h)

        c_outer = sg.Point(2.0, m_base.bounds[1][1] + 1.80).buffer(4.20, resolution=32)
        c_inner = sg.Point(2.0, m_base.bounds[1][1] + 1.80).buffer(1.90, resolution=32)
        poly_eyelet = c_outer.difference(c_inner)
        m_eyelet = _extrude_poly(poly_eyelet, height=2.60)

        verts_b = np.ascontiguousarray(m_base.vertices, dtype=np.float32)
        faces_b = np.ascontiguousarray(m_base.faces, dtype=np.uint32)
        verts_e = np.ascontiguousarray(m_eyelet.vertices, dtype=np.float32)
        faces_e = np.ascontiguousarray(m_eyelet.faces, dtype=np.uint32)
        m_base_loop = (Manifold(Mesh(vert_properties=verts_b, tri_verts=faces_b)) + Manifold(Mesh(vert_properties=verts_e, tri_verts=faces_e))).to_mesh()
        m_base_with_loop = trimesh.Trimesh(vertices=m_base_loop.vert_properties[:, :3], faces=m_base_loop.tri_verts, process=False)

        return {
            'base': m_base_with_loop,
            'text': m_text,
            'base_mesh': m_base_with_loop,
            'text_mesh': m_text
        }

    raise FileNotFoundError("Mesh master CAD Huntrix non trovata!")

def get_huntrix_preset_b_geometries(heart_width: float = 50.0) -> Dict[str, Any]:
    """
    Preset B: Cuore a 3 Livelli e 3 Colori Indipendenti
    - Level 1: Base_Slab (offset +2.0 mm con occhiello centrale a X=0, Z [0.0, 2.40] mm, Tool 0)
    - Level 2: Heart_Body (cuore reale pieno ricalcato dalla foto, Z [2.00, 3.60] mm, Tool 1)
    - Level 3: Mesh_Text (logo autentico HUNTRIX 1:1 piatto, Z [3.20, 4.40] mm, Tool 2)
    """
    scale = heart_width / 50.0
    heart = get_real_heart_polygon(heart_width=heart_width)
    base_offset = heart.buffer(2.0 * scale, resolution=32)

    eyelet_center = sg.Point(0.0, 24.5 * scale)
    r_inner = 1.9 * scale
    r_outer = 4.2 * scale
    eyelet_outer = eyelet_center.buffer(r_outer, resolution=32)
    neck_box = sg.box(-3.5 * scale, 18.0 * scale, 3.5 * scale, 24.5 * scale)
    eyelet_tab = eyelet_outer.union(neck_box)
    eyelet_inner = eyelet_center.buffer(r_inner, resolution=32)
    base_slab = base_offset.union(eyelet_tab).difference(eyelet_inner)

    # Logo autentico proporzionato (larghezza 36.0 mm)
    target_w_text = 36.0 * scale
    logo_scaled = get_authentic_huntrix_logo(target_width=target_w_text, buffer_fdm=0.12)
    # Centrato nella porzione ampia del cuore attorno a Y = +3.5 mm
    logo_placed = affinity.translate(logo_scaled, yoff=3.5 * scale)

    # Livello 1: Base_Slab Z in [0.0, 2.40] mm
    m_base = _extrude_poly(base_slab, 2.40)

    # Livello 2: Heart_Body Z in [2.00, 3.60] mm (altezza 1.60 mm, overlap 0.40 mm)
    m_heart = _extrude_poly(heart, 1.60)
    m_heart.apply_translation([0, 0, 2.00])

    # Livello 3: Mesh_Text Z in [3.20, 4.40] mm (prisma retto piatto, altezza 1.20 mm, overlap 0.40 mm)
    m_text = _extrude_poly(logo_placed, 1.20)
    m_text.apply_translation([0, 0, 3.20])

    return {
        'base': base_slab,
        'heart': heart,
        'text': logo_placed,
        'base_mesh': m_base,
        'heart_mesh': m_heart,
        'text_mesh': m_text
    }
